def get_valid_import_records(apps, cursor):
    """
    Return a mapping of the plugin's import records whose target objects still exist to their entry types.
    """
    ContentType = apps.get_model('contenttypes', 'ContentType')

    cursor.execute(f'SELECT id, content_type_id, object_id FROM {PLUGIN_IMPORT_RECORD_TABLE}')
    records_by_type = defaultdict(list)
    for pk, content_type_id, object_id in cursor.fetchall():
        records_by_type[content_type_id].append((pk, object_id))

    valid = {}
    for content_type in ContentType.objects.filter(pk__in=list(records_by_type)):
        try:
            model = apps.get_model(content_type.app_label, content_type.model)
        except LookupError:
            continue
        records = records_by_type[content_type.pk]
        existing = set(
            model.objects.filter(pk__in=[object_id for _, object_id in records]).values_list('pk', flat=True)
        )
        entry_type = ENTRY_TYPES.get((content_type.app_label, content_type.model), content_type.model)
        valid.update({pk: entry_type for pk, object_id in records if object_id in existing})
    return valid


